CREATE UNLOGGED TABLE IF NOT EXISTS rate_limits (
    key TEXT PRIMARY KEY,
    tokens INTEGER NOT NULL,
    last_refill TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE POLICY "Public Access" ON storage.objects 
  FOR SELECT 
  USING ( bucket_id IN ('logos', 'covers', 'team_photos', 'service_images', 'client_photos') );

CREATE POLICY "Auth Upload" ON storage.objects 
  FOR INSERT 
  WITH CHECK ( auth.role() = 'authenticated' AND bucket_id IN ('logos', 'covers', 'team_photos', 'service_images', 'client_photos') );

CREATE POLICY "Auth Update" ON storage.objects 
  FOR UPDATE 
  USING ( auth.role() = 'authenticated' AND bucket_id IN ('logos', 'covers', 'team_photos', 'service_images', 'client_photos') );

CREATE POLICY "Auth Delete" ON storage.objects 
  FOR DELETE 
  USING ( auth.role() = 'authenticated' AND bucket_id IN ('logos', 'covers', 'team_photos', 'service_images', 'client_photos') );

CREATE POLICY "Public can view active queue" ON queue_entries
    FOR SELECT
    USING (status NOT IN ('completed', 'cancelled', 'no_show'));

CREATE POLICY "Business owners view all their queue" ON queue_entries
    FOR SELECT
    USING (auth.uid() = business_id);

CREATE POLICY "Business owners manage their queue" ON queue_entries
    FOR INSERT
    WITH CHECK (auth.uid() = business_id);

CREATE POLICY "Business owners update their queue" ON queue_entries
    FOR UPDATE
    USING (auth.uid() = business_id);

CREATE POLICY "Business owners delete their queue" ON queue_entries
    FOR DELETE
    USING (auth.uid() = business_id);

CREATE POLICY "Public can register as client" ON public_clients
    FOR INSERT
    WITH CHECK (true);

CREATE POLICY "Business owners can view their public clients" ON public_clients
    FOR ALL
    USING (auth.uid() = business_id);

CREATE POLICY "Public can join queue" ON queue_entries
    FOR INSERT
    WITH CHECK (true);

