CREATE POLICY "Users manage own upsells"
  ON service_upsells FOR ALL
  USING (
    EXISTS (
      SELECT 1 FROM services
      WHERE services.id = service_upsells.parent_service_id
      AND services.user_id = auth.uid()
    )
  );

