  ON profiles FOR SELECT
  USING (true);

CREATE POLICY "audit_logs_read" ON audit_logs
  FOR SELECT
  TO authenticated
  USING (

    company_id = (
      SELECT company_id FROM profiles WHERE id = auth.uid()
    )
  );

CREATE POLICY "client_semantic_memory_company_isolation" ON client_semantic_memory
  FOR ALL
  TO authenticated
  USING (


    client_id IN (
      SELECT id FROM clients
      WHERE company_id = (
        SELECT company_id FROM profiles WHERE id = auth.uid()
      )
    )
  )
  WITH CHECK (

    client_id IN (
      SELECT id FROM clients
      WHERE company_id = (
        SELECT company_id FROM profiles WHERE id = auth.uid()
      )
    )
  );

CREATE POLICY IF NOT EXISTS "Profiles: company isolation"
  ON profiles
  FOR SELECT
  TO authenticated
  USING (


    id = auth.uid() OR

    company_id = (
      SELECT company_id FROM profiles WHERE id = auth.uid()
    ) OR

    id = (
      SELECT company_id FROM profiles WHERE id = auth.uid()
    )
  );

CREATE POLICY "Profiles: users cant insert"
  ON profiles FOR INSERT TO authenticated
  WITH CHECK (false);

CREATE POLICY "Profiles: users cant delete"
  ON profiles FOR DELETE TO authenticated
  USING (false);

CREATE POLICY "Commissions: staff select own"
  ON public.commission_payments
  FOR SELECT
  TO authenticated
  USING (
    company_id = get_auth_company_id()
    AND collaborator_id IN (
      SELECT id FROM public.team_members WHERE user_id = auth.uid()
    )
  );

CREATE POLICY "Staff can view own commissions"
    ON public.finance_records
    FOR SELECT
    USING (
        EXISTS (
            SELECT 1 FROM public.team_members tm
            WHERE tm.id = professional_id
              AND tm.staff_user_id = auth.uid()
        )
    );

