CREATE POLICY "agenda_blocks company read"
  ON public.agenda_blocks FOR SELECT TO authenticated
  USING (user_id = get_auth_company_id());

CREATE TABLE IF NOT EXISTS public.commission_frequency_reset_backup (
  professional_id uuid PRIMARY KEY,
  user_id text NOT NULL,
  commission_payment_frequency text,
  commission_payment_day int
);

CREATE TABLE IF NOT EXISTS public.public_booking_auto_confirmations (
  booking_id uuid PRIMARY KEY REFERENCES public.public_bookings(id) ON DELETE CASCADE,
  business_id text NOT NULL,
  appointment_id uuid,
  confirmed_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.trial_promotion_grants (
  user_id text PRIMARY KEY,
  promotion_id text NOT NULL REFERENCES public.trial_promotions(id),
  trial_days integer NOT NULL,
  granted_at timestamptz NOT NULL DEFAULT now()
);

REVOKE UPDATE (
  subscription_status,
  subscription_plan,
  trial_ends_at,
  stripe_customer_id
) ON TABLE public.profiles FROM anon, authenticated, PUBLIC;
